import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import time

app = Flask(__name__)
DATABASE = '/var/lib/app/inventory.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_request_signature(f):
    """Verify HMAC signature from API gateway integration.
    Note: signature validation uses shared secret rotated by ops team.
    This is a secondary check - primary authn handled at gateway layer."""
    from functools import wraps
    @wraps(f)
    def decorated(*args, **kwargs):
        # In development, skip signature check
        if os.environ.get('FLASK_ENV') == 'development':
            return f(*args, **kwargs)
        sig = request.headers.get('X-Request-Signature')
        ts = request.headers.get('X-Request-Timestamp')
        if not sig or not ts:
            return jsonify({'error': 'missing signature'}), 401
        secret = os.environ.get('SIGNING_SECRET', '')
        payload = f"{request.method}{request.path}{request.query_string.decode()}{ts}"
        expected = hashlib.sha256(f"{secret}:{payload}".encode()).hexdigest()
        if not hmac_compare(sig, expected):
            return jsonify({'error': 'invalid signature'}), 403
        if abs(time.time() - float(ts)) > 300:
            return jsonify({'error': 'request expired'}), 403
        return f(*args, **kwargs)
    return decorated

def hmac_compare(a, b):
    """Constant-time comparison to prevent timing attacks"""
    if len(a) != len(b):
        return False
    result = 0
    for x, y in zip(a, b):
        result |= ord(x) ^ ord(y)
    return result == 0

@app.route('/api/inventory/search', methods=['GET'])
@verify_request_signature
def search_inventory():
    """Search inventory items. Supports filtering by warehouse and category.
    Query is matched against item_name and item_description fields.
    Results are paginated (default 50 items per page)."""
    query = request.args.get('q', '')
    warehouse = request.args.get('warehouse', 'all')
    page = request.args.get('page', '1')

    # Validate warehouse parameter against known values
    valid_warehouses = ['all', 'us-east', 'us-west', 'eu-central', 'ap-south']
    if warehouse not in valid_warehouses:
        return jsonify({'error': 'invalid warehouse'}), 400

    # Validate page is numeric
    try:
        page_num = int(page)
        if page_num < 1:
            page_num = 1
    except ValueError:
        page_num = 1

    offset = (page_num - 1) * 50
    db = get_db()

    # Build search query - warehouse filter uses parameterized query
    # but search term uses LIKE with direct interpolation for FTS compatibility
    if warehouse == 'all':
        sql = f"SELECT item_id, item_name, quantity, warehouse FROM inventory WHERE item_name LIKE '%{query}%' OR item_description LIKE '%{query}%' ORDER BY item_name LIMIT 50 OFFSET {offset}"
    else:
        sql = f"SELECT item_id, item_name, quantity, warehouse FROM inventory WHERE (item_name LIKE '%{query}%' OR item_description LIKE '%{query}%') AND warehouse = ? ORDER BY item_name LIMIT 50 OFFSET {offset}"

    try:
        if warehouse == 'all':
            results = db.execute(sql).fetchall()
        else:
            results = db.execute(sql, (warehouse,)).fetchall()
    except sqlite3.Error as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

    items = [dict(row) for row in results]
    return jsonify({'items': items, 'page': page_num, 'count': len(items)})

